def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A 3-by-3 ring with a 2 center marks a ray along the grid's divider
    # orientation. Extend the ray as 1s, making short perpendicular branches
    # at each matching divider crossing.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                               (r,c-1),(r,c+1),
                               (r+1,c-1),(r+1,c),(r+1,c+1))
            ):
                centers.append((r, c))

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 1

    for r, c in centers:
        vertical_bar = all(grid[rr][c] == 2 for rr in range(h))
        horizontal_bar = all(grid[r][cc] == 2 for cc in range(w))
        if vertical_bar:
            # Continue horizontally along the center row.
            for cc in range(w):
                paint(r, cc)
            # At each vertical divider, add the two side cells above/below.
            for cc in range(w):
                if all(grid[rr][cc] == 2 for rr in range(h)):
                    for dc in (-1, 1):
                        paint(r-1, cc+dc)
                        paint(r+1, cc+dc)
        elif horizontal_bar:
            # Continue vertically along the center column.
            for rr in range(h):
                paint(rr, c)
            # At each horizontal divider, add the two side cells left/right.
            for rr in range(h):
                if all(grid[rr][cc] == 2 for cc in range(w)):
                    for dr in (-1, 1):
                        paint(rr+dr, c-1)
                        paint(rr+dr, c+1)
    return out
