def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A divider is an almost-entire line of 2s; the 3x3 marker may interrupt it.
    hlines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 3]
    vlines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 3]

    rings = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                               (r,c-1),(r,c+1),
                               (r+1,c-1),(r+1,c),(r+1,c+1))
            ):
                rings.append((r, c))

    rays = []
    for r, c in rings:
        if r in hlines:
            rays.append(("vertical", r, c))
        elif c in vlines:
            rays.append(("horizontal", r, c))

    # The ray continues straight through the marker, preserving all 2/3 cells.
    for direction, r, c in rays:
        if direction == "vertical":
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
        else:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1

    # At crossings with other dividers, draw a 3x3 flare, leaving the crossing
    # 2 and any original 3s intact.
    for direction, r, c in rays:
        crossings = hlines if direction == "vertical" else vlines
        source_line = r if direction == "vertical" else c
        for line in crossings:
            if line == source_line:
                continue
            for rr in range(max(0, r - 1), min(h, r + 2)) if direction == "horizontal" else range(max(0, line - 1), min(h, line + 2)):
                for cc in range(max(0, line - 1), min(w, line + 2)) if direction == "horizontal" else range(max(0, c - 1), min(w, c + 2)):
                    if (rr, cc) == ((r, line) if direction == "horizontal" else (line, c)):
                        continue
                    if grid[rr][cc] != 3:
                        out[rr][cc] = 1
    return out
